os","trecho":"Rua Amando de Barros na área do rotativo","aproximado":true,"nota_trecho":null,"osm_way_id":203094190,"nome_osm":"Rua Amando de Barros","mao_unica":true,"sentido":"unico","comprimento_m":1130,"verificado_em":"2026-10-11"}$q$::jsonb, $q$2012-03-01$q$::timestamptz, null::timestamptz),
