insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$botucatu$q$, $q$https://www.botucatu.sp.gov.br/legislacao/download-lei/11176/ (Dec. 10.866/2017) ; https://www.botucatu.sp.gov.br/legislacao/download-lei/11162/ (Dec. 10.881/2017) ; https://www.dosp.com.br/exibe_do.php?i=NTIyOTc3 (Semanário Oficial nº 1035, 07/01/2010: Resoluções DET 001/10 e 02/10)$q$, $q$Atos oficiais de Botucatu: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 79, $q$Ativas: Rodovia Alcides Soares (BTC-010), km 2 a 14, bitrem e treminhão proibidos (Decs. 10.866 e 10.881/2017); Av. Dom Lúcio (entre R. Manoel Fernandes Cardoso e R. Carlino de Oliveira) e R. Firmino Pontes Ribeiro (acesso de César Neto sob a ponte da Fepasa), caminhão com mais de 2 eixos proibido (Res. DET 02/10 e 001/10). Desativadas: treminhão na BTC-010 inteira (o perfil não distingue treminhão de bitrem), carga e descarga nas vias centrais (sem delimitação), R. Amando de Barros (texto ambíguo) e cana na área urbana (critério de carga).$q$);
